cd /tmp/gh2200 && grep -c "✅" pty2.log && python3 - <<'EOF'
import re, json
# target files from the log
targets = []
started = False
for line in open('pty2.log'):
    if 'shard targets:' in line:
        started = True; continue
    if started:
        m = re.match(r'^\S*Z (test/\S+\.dart)\s*$', line)
        if m: targets.append(m.group(1))
        else: started = False
print("targets:", len(targets))
done = set()
for line in open('pty2.log'):
    m = re.search(r'✅ (test/\S+\.dart):', line)
    if m: done.add(m.group(1))
print("files with passing tests observed:", len(done))
missing = [t for t in targets if t not in done]
print("files with NO passing test observed (candidates for the hang):")
for t in missing: print("  ", t)
EOF

