//       trajectory/cli_integration_test.dart" although the rerun shard
//       passed every test. The primary upload must replace its previous
//       attempt's artifact so reruns are idempotent and the merged gate
//       always reads the freshest complete evidence.

    test(
      'AC3: retries stay always()-reachable and never continue-on-error',
      () {
        for (final retry in retries) {
          expect(
            retry['if']?.toString(),
            contains('always()'),
            reason:
                'the gh-1412 retries must stay reachable on red legs — '
                'the evidence uploads run if: always() so a red run keeps '
                'its timing/coverage evidence (the retry inherits that '
                'contract)',
          );
