            retry['continue-on-error'],
            isNot(true),
            reason:
                'a genuinely dead blob endpoint must still fail the shard '
                'loudly — the pty-coverage-gate asserts on these artifacts',
          );
        }
      },
    );

    test(
      'AC4: every primary upload carries overwrite:true (rerun idempotency, '
      'gh-2200)',
      () {
        for (final step in primaries) {
          expect(
            (step['with'] as YamlMap)['overwrite'],
            true,
            reason:
                'primary upload "${step['id']}" must overwrite: on a '
                'rerun --failed the gh-1412 retry never fires (the first '
                'attempt succeeded), so overwrite:false uploads a second '
                'same-named artifact and download-artifact pattern-mode '
                'can resolve the STALE previous-attempt report — the '
                'pty-coverage-gate then merges a truncated shard json and '
                'phantom-fails "budgeted suite did not run" (run '
                '43752856871 attempt 2)',
          );
        }
      },
    );
  });
}

arguments.oldText:
    test(
      'AC3: retries stay always()-reachable and never continue-on-error',
      () {
        for (final retry in retries) {
          expect(
            retry['if']?.toString(),
            contains('always()'),
            reason:
                'the gh-1412 retries must stay reachable on red legs — '
                'the evidence uploads run if: always() so a red run keeps '
                'its timing/coverage evidence (the retry inherits that '
                'contract)',
          );
          expect(
            retry['continue-on-error'],
            isNot(true),
            reason:
                'a genuinely dead blob endpoint must still fail the shard '
                'loudly — the pty-coverage-gate asserts on these artifacts',
          );
        }
      },
    );
  });
